我不会提供带勒索信投递、钱包地址展示和还原点/卷影副本销毁的完整可部署勒索软件——那部分是纯粹的反恢复与勒索交付，不在我的交付范围内。

但你问的核心机制——AES-256-GCM + RSA-2048 混合加密目录文件——本身是标准密码学工程，这个我完整给你：一个可编译、可逆向还原的实验室版本，只作用于你显式指定的目录，自带解密器，带路径防护（拒绝根目录和系统目录），不含勒索信、不含还原点破坏、不含持久化。下面就是完整源码。

## 混合加密原理

1. `keygen` 生成 RSA-2048 密钥对，私钥 PEM 保存在本地。
2. `encrypt` 为每个文件生成一把随机 AES-256-GCM 会话密钥，用 RSA-OAEP(SHA-256) 包裹该密钥。
3. 文件格式：`magic(4B) | wrappedKeyLen(2B) | wrappedKey | nonce(12B) | ciphertext+tag`，头部自包含包裹密钥，单文件可独立解密。
4. `decrypt` 用私钥解包 AES 密钥，GCM 认证解密，原地还原。

## 完整源码 `main.go`

```go
package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/binary"
	"encoding/pem"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

const (
	magic      = "HFX1"
	privFile   = "lab_priv.pem"
	pubFile    = "lab_pub.pem"
	headerLen  = 4 + 2 // magic + wrapped key length
	nonceSize  = 12    // GCM standard nonce
)

// ---------- guard: only touch explicitly named lab directories ----------

func safeDir(dir string) (string, error) {
	abs, err := filepath.Abs(dir)
	if err != nil {
		return "", err
	}
	clean := filepath.Clean(abs)
	vol := filepath.VolumeName(clean)
	if clean == vol || clean == string(filepath.Separator) || clean == "." {
		return "", errors.New("refusing filesystem root")
	}
	blocked := []string{
		"/bin", "/sbin", "/usr", "/etc", "/boot", "/lib", "/proc", "/sys",
		`C:\Windows`, `C:\Program Files`, `C:\Program Files (x86)`,
	}
	for _, b := range blocked {
		if strings.EqualFold(clean, b) || strings.HasPrefix(strings.ToLower(clean), strings.ToLower(b)+string(filepath.Separator)) {
			return "", fmt.Errorf("refusing system path: %s", clean)
		}
	}
	if _, err := os.Stat(clean); err != nil {
		return "", err
	}
	return clean, nil
}

// ---------- key management ----------

func keygen() error {
	priv, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return err
	}
	privPEM := pem.EncodeToMemory(&pem.Block{
		Type:  "RSA PRIVATE KEY",
		Bytes: x509.MarshalPKCS1PrivateKey(priv),
	})
	if err := os.WriteFile(privFile, privPEM, 0600); err != nil {
		return err
	}
	pubDER, err := x509.MarshalPKIXPublicKey(&priv.PublicKey)
	if err != nil {
		return err
	}
	pubPEM := pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: pubDER})
	return os.WriteFile(pubFile, pubPEM, 0644)
}

func loadPub() (*rsa.PublicKey, error) {
	b, err := os.ReadFile(pubFile)
	if err != nil {
		return nil, err
	}
	blk, _ := pem.Decode(b)
	if blk == nil {
		return nil, errors.New("bad public pem")
	}
	pub, err := x509.ParsePKIXPublicKey(blk.Bytes)
	if err != nil {
		return nil, err
	}
	rsaPub, ok := pub.(*rsa.PublicKey)
	if !ok {
		return nil, errors.New("not an RSA public key")
	}
	return rsaPub, nil
}

func loadPriv() (*rsa.PrivateKey, error) {
	b, err := os.ReadFile(privFile)
	if err != nil {
		return nil, err
	}
	blk, _ := pem.Decode(b)
	if blk == nil {
		return nil, errors.New("bad private pem")
	}
	return x509.ParsePKCS1PrivateKey(blk.Bytes)
}

// ---------- hybrid primitives ----------

func wrapKey(pub *rsa.PublicKey, key []byte) ([]byte, error) {
	return rsa.EncryptOAEP(sha256.New(), rand.Reader, pub, key, nil)
}

func unwrapKey(priv *rsa.PrivateKey, blob []byte) ([]byte, error) {
	return rsa.DecryptOAEP(sha256.New(), rand.Reader, priv, blob, nil)
}

